1	//! SoA envelope little-endian contract.
2	//!
3	//! # Why this module exists
4	//!
5	//! Column-level LE knowledge is not enough. ndarray's `MultiLaneColumn`
6	//! (the column carrier) already decodes its own bytes little-endian, and
7	//! `CausalEdge64` / `EpisodicEdges64` each know their own `to_le_bytes` /
8	//! `from_le_bytes`. But the **SoA envelope as a whole** — the thing a Lance
9	//! version snapshots, the thing `simd_soa` sweeps, the thing a future reader
10	//! decodes — has no contract describing how those columns *assemble* into one
11	//! row-strided packet. The parts know the LE contract; the envelope did not.
12	//!
13	//! [`SoaEnvelope`] is that missing contract. It makes the in-place SoA
14	//! backing store **self-describing at each cycle**: a stable column ordering,
15	//! a fixed row byte stride, a `cycle` version stamp, and a
16	//! [`ENVELOPE_LAYOUT_VERSION`]. With it, a Lance version IS a coherent LE
17	//! in-place layout at cycle N — not a loose collection of independently-
18	//! correct columns. Nothing is serialized or transmitted; the backing bytes
19	//! are resident in-place, zero-copy from creation to Lance tombstone.
20	//!
21	//! # Layering (read before adding an ndarray dependency here)
22	//!
23	//! This module is **zero-dep, byte-geometry only**. It describes *where*
24	//! columns sit in the backing store's row stride and *what* LE element each
25	//! holds — as data ([`ColumnDescriptor`]), never as ndarray generic bounds.
26	//! That keeps `lance-graph-contract` featherweight for its non-HPC consumers
27	//! (OGAR classes, ractor actors), and it keeps ndarray usable standalone by
28	//! any pure-SIMD consumer.
29	//!
30	//! The split is deliberate and complementary, not duplicated:
31	//!
32	//! | Level | Home | Answers |
33	//! |-------|------|---------|
34	//! | Column LE contract | `ndarray::simd::MultiLaneColumn` | "how do I sweep one typed column" |
35	//! | Envelope LE contract | this module | "where do columns sit in the row stride, what cycle is this" |
36	//! | Composition | `lance-graph` (always has both deps) | carve envelope columns → wrap each in `MultiLaneColumn` |
37	//!
38	//! ndarray never learns the envelope exists; this crate never learns ndarray
39	//! exists; `lance-graph` binds them.
40	
41	/// Layout version of the envelope byte geometry.
42	///
43	/// Bumped whenever the meaning of [`ColumnDescriptor`] offsets/strides
44	/// changes. A reader MUST refuse to decode a packet whose stamped version it
45	/// does not understand (per `I-LEGACY-API-FEATURE-GATED`: layout reclaim is
46	/// paired with a version gate on the serialization path).
47	///
48	/// - **v1** — initial canonical `NodeRow` value carve.
49	/// - **v2** — `HelixResidue` value-tenant right-sized 48 B → 6 B (a bits→bytes
50	///   slip fix), which shifted every downstream tenant offset (`TurbovecResidue`
51	///   160→118, `Energy` 176→134, …). The offsets moved, so the version gates it:
52	///   a v1 blob now refuses to decode rather than read tenants from the wrong
53	///   bytes. Safe because nothing persisted under v1 (FULL is POC-only).
54	pub const ENVELOPE_LAYOUT_VERSION: u8 = 2;
55	
56	/// The little-endian element type of one column.
57	///
58	/// Width only — no distance semantics, no domain meaning (cf. ndarray's
59	/// no-umbrella rule). The actual decode (`from_le_bytes`) happens in the
60	/// consumer's `MultiLaneColumn` lane iterator.
61	#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
62	#[repr(u8)]
63	pub enum ColumnKind {
64	    U8 = 0,
65	    I8 = 1,
66	    U16 = 2,
67	    I16 = 3,
68	    U32 = 4,
69	    F32 = 5,
70	    U64 = 6,
71	    F64 = 7,
72	}
73	
74	impl ColumnKind {
75	    /// Bytes per element of this LE column kind.
76	    pub const fn elem_bytes(self) -> usize {
77	        match self {
78	            ColumnKind::U8 | ColumnKind::I8 => 1,
79	            ColumnKind::U16 | ColumnKind::I16 => 2,
80	            ColumnKind::U32 | ColumnKind::F32 => 4,
81	            ColumnKind::U64 | ColumnKind::F64 => 8,
82	        }
83	    }
84	}
85	
86	/// One column's placement within a single row of the backing store.
87	///
88	/// `Copy` and `repr(C)` so a descriptor table is itself a stable LE artifact.
89	/// `name_id` is a stable column ordinal (an enum discriminant on the consumer
90	/// side), NOT a string — keeping this crate alloc-free and the descriptor
91	/// `Copy`.
92	#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
93	#[repr(C)]
94	pub struct ColumnDescriptor {
95	    /// Stable column identity (consumer-side enum ordinal).
96	    pub name_id: u16,
97	    /// LE element kind.
98	    pub kind: ColumnKind,
99	    /// Elements of `kind` per row for this column (e.g. content = 256 × u64,
100	    /// energy = 1 × f32).
101	    pub elems_per_row: u16,
102	    /// Byte offset of this column within one row packet.
103	    pub row_offset: u32,
104	}
105	
106	impl ColumnDescriptor {
107	    /// Bytes this column occupies in one row.
108	    pub const fn col_bytes_per_row(&self) -> usize {
109	        self.kind.elem_bytes() * self.elems_per_row as usize
110	    }
111	
112	    /// Byte range `[start, end)` of this column within a row packet.
113	    pub const fn row_byte_range(&self) -> (usize, usize) {
114	        let start = self.row_offset as usize;
115	        (start, start + self.col_bytes_per_row())
116	    }
117	}
118	
119	/// What can go wrong validating an envelope's byte geometry.
120	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
121	pub enum EnvelopeError {
122	    /// The stamped layout version is not the one this build understands.
123	    LayoutVersionMismatch { expected: u8, found: u8 },
124	    /// Sum of column byte-widths does not equal the declared row stride.
125	    StrideMismatch { declared: usize, summed: usize },
126	    /// Two columns overlap, or a gap/ordering violation was found.
127	    ColumnOverlap { col_a: u16, col_b: u16 },
128	    /// A column's byte range ends past the declared row stride. Distinct from
129	    /// [`StrideMismatch`]: the widths can sum to the stride while a column is
130	    /// still positioned (via its `row_offset`) so its end exceeds the stride.
131	    ColumnOutOfBounds {
132	        col: u16,
133	        col_end: usize,
134	        stride: usize,
135	    },
136	    /// `as_le_bytes().len()` is not `row_stride * n_rows` (backing store size mismatch).
137	    PacketSizeMismatch { expected: usize, found: usize },
138	    /// A requested row or column index is out of bounds.
139	    OutOfBounds,
140	}
141	
142	/// The little-endian geometry contract for one SoA envelope cycle.
143	///
144	/// Implemented by the owner of the in-place backing store (e.g. the mailbox
145	/// SoA). The envelope is zero-copy from creation to Lance tombstone — nothing
146	/// is serialized or transmitted; this trait describes *where columns sit* in
147	/// the already-resident backing bytes and *what cycle stamp* the store carries.
148	/// The read-only view here mirrors `MailboxSoaView` vs `MailboxSoaOwner`:
149	/// mutation lives on the owner type, never on this trait.
150	///
151	/// # Ownership inheritance — up and down (operator, 2026-07-02)
152	///
153	/// The LE contract IS the ownership carrier, in both directions:
154	///
155	/// - **Structurally (compile time):** every view this trait hands out
156	///   ([`as_le_bytes`](SoaEnvelope::as_le_bytes) / [`row_le`](SoaEnvelope::row_le)
157	///   / [`column_le`](SoaEnvelope::column_le)) is a `&self` borrow OF the
158	///   implementing owner — a view cannot outlive or alias the mailbox that
159	///   owns the backing store, and a batch-writer cast (`&mut` on the owner)
160	///   cannot begin while any view is live. Rust's borrow rules ARE the
161	///   inheritance; nothing is checked at runtime.
162	/// - **Nominally (provenance):** [`mailbox_owner`](SoaEnvelope::mailbox_owner)
163	///   stamps WHICH mailbox owns these bytes, so the ownership survives the
164	///   two places borrows cannot reach — DOWN into Lance (the tombstone
165	///   records whose mailbox wrote the packet) and UP to consumers (every
166	///   consuming crate writes ON BEHALF OF this id, never directly — the
167	///   fleet-wide write-on-behalf rule; a write cast naming a different
168	///   mailbox than the envelope's stamp is the delegation case the batch
169	///   writer's cache logic resolves at cast time).
170	pub trait SoaEnvelope {
171	    /// Layout version this implementor's geometry conforms to.
172	    const LAYOUT_VERSION: u8 = ENVELOPE_LAYOUT_VERSION;
173	
174	    /// Stable, ordered column placement table. Ordering is part of the
175	    /// contract: a reader walks columns in this order.
176	    fn columns(&self) -> &[ColumnDescriptor];
177	
178	    /// Total bytes per row across all columns.
179	    fn row_stride(&self) -> usize;
180	
181	    /// Number of rows in this snapshot.
182	    fn n_rows(&self) -> usize;
183	
184	    /// The version stamp this snapshot carries (the cycle whose committed
185	    /// state these bytes are). This is what turns a Lance version into a
186	    /// coherent "packet at cycle N".
187	    fn cycle(&self) -> u32;
188	
189	    /// The mailbox that OWNS this envelope's backing store — the nominal half
190	    /// of the up/down ownership inheritance (see the trait docs). `0` is the
191	    /// bootstrap/unowned stamp per the zero-fallback ladder (RESERVE, DON'T
192	    /// RECLAIM: default = not consulted, never absent); a real mailbox
193	    /// overrides with its [`MailboxId`](crate::collapse_gate::MailboxId).
194	    /// Consumers write on behalf of THIS id, never directly.
195	    fn mailbox_owner(&self) -> crate::collapse_gate::MailboxId {
196	        0
197	    }
198	
199	    /// The whole packet as contiguous LE bytes, zero-copy. Length MUST be
200	    /// `row_stride() * n_rows()`.
201	    fn as_le_bytes(&self) -> &[u8];
202	
203	    /// Zero-copy LE view of one full row.
204	    fn row_le(&self, row: usize) -> Option<&[u8]> {
205	        let stride = self.row_stride();
206	        let start = row.checked_mul(stride)?;
207	        let end = start.checked_add(stride)?;
208	        self.as_le_bytes().get(start..end)
209	    }
210	
211	    /// Zero-copy LE view of one column within one row.
212	    fn column_le(&self, row: usize, col: &ColumnDescriptor) -> Option<&[u8]> {
213	        let r = self.row_le(row)?;
214	        let (start, end) = col.row_byte_range();
215	        r.get(start..end)
216	    }
217	
218	    /// Validate that the declared geometry is internally consistent and that
219	    /// the backing packet matches. Call this at the Lance read boundary — a
220	    /// v1 packet under a v2 reader (or a torn snapshot) is refused here rather
221	    /// than silently mis-decoded downstream.
222	    fn verify_layout(&self) -> Result<(), EnvelopeError> {
223	        // 1. Version gate.
224	        if Self::LAYOUT_VERSION != ENVELOPE_LAYOUT_VERSION {
225	            return Err(EnvelopeError::LayoutVersionMismatch {
226	                expected: ENVELOPE_LAYOUT_VERSION,
227	                found: Self::LAYOUT_VERSION,
228	            });
229	        }
230	        // 2. Columns are non-overlapping, each fits within [0, stride), and
231	        //    their widths sum to the stride.
232	        //    Checking only the width sum is insufficient: two columns whose
233	        //    widths sum to the stride can still have one column whose end
234	        //    offset exceeds the stride (e.g. offsets 4+8 with stride 8).
235	        let cols = self.columns();
236	        let mut summed = 0usize;
237	        let stride = self.row_stride();
238	        // `row_offset as usize + col_bytes` can wrap on 32-bit targets (wasm32):
239	        // row_offset is u32 (≤ 4.29e9) and col_bytes can reach 8 × 65535, so the
240	        // sum can exceed usize::MAX on a 32-bit usize and wrap to a small value
241	        // that would slip past the `a_end > stride` check. Compute every end with
242	        // checked_add and reject overflow as ColumnOutOfBounds.
243	        let checked_end = |c: &ColumnDescriptor| -> Result<usize, EnvelopeError> {
244	            (c.row_offset as usize)
245	                .checked_add(c.col_bytes_per_row())
246	                .ok_or(EnvelopeError::ColumnOutOfBounds {
247	                    col: c.name_id,
248	                    col_end: usize::MAX,
249	                    stride,
250	                })
251	        };
252	        for (i, a) in cols.iter().enumerate() {
253	            let a_start = a.row_offset as usize;
254	            let a_end = checked_end(a)?;
255	            summed += a.col_bytes_per_row();
256	            if a_end > stride {
257	                return Err(EnvelopeError::ColumnOutOfBounds {
258	                    col: a.name_id,
259	                    col_end: a_end,
260	                    stride,
261	                });
262	            }
263	            for b in &cols[i + 1..] {
264	                let b_start = b.row_offset as usize;
265	                let b_end = checked_end(b)?;
266	                let overlap = a_start < b_end && b_start < a_end;
267	                if overlap {
268	                    return Err(EnvelopeError::ColumnOverlap {
269	                        col_a: a.name_id,
270	                        col_b: b.name_id,
271	                    });
272	                }
273	            }
274	        }
275	        if summed != stride {
276	            return Err(EnvelopeError::StrideMismatch {
277	                declared: stride,
278	                summed,
279	            });
280	        }
281	        // 3. Backing packet size matches stride × rows.
282	        let expected = stride.saturating_mul(self.n_rows());
283	        let found = self.as_le_bytes().len();
284	        if expected != found {
285	            return Err(EnvelopeError::PacketSizeMismatch { expected, found });
286	        }
287	        Ok(())
288	    }
289	}
