4	//! `rubicon_witness` — reading which side of the Rubicon the thinking is on,
5	//! from the focus of attention alone (`D-ACR-8`).
6	//!
7	//! # What Heckhausen actually asserts, and why a focus mask can falsify it
8	//!
9	//! `unified-soa-rubikon-integration-v1.md` §3 maps the Heckhausen action phases
10	//! onto the kanban columns, and the crossing sits on
11	//! [`Planning`](KanbanColumn::Planning) →
12	//! [`CognitiveWork`](KanbanColumn::CognitiveWork). The claim the model makes
13	//! about that crossing is a claim about **attention**:
14	//!
15	//! > **Pre-Rubicon = deliberative mindset:** open, broad, impartial — many
16	//! > candidates held at once.
17	//! > **Post-Rubicon = implemental mindset:** narrow, partial, *shielding* — the
18	//! > intention is protected against reconsideration.
19	//!
20	//! A [`RowFocusMask`] measures exactly that, so the alpha channel does not
21	//! merely *accompany* the phase labels — **it is the instrument that can
22	//! falsify them**. If the two phases read the same on a genuinely deliberated
23	//! task, then either the kanban columns are decoration or the focus mask is not
24	//! recording attention, and both are findings worth having.
25	//!
26	//! # It READS. It never moves anything.
27	//!
28	//! Phase movement stays `advance_on_gate`, and the standing tombstone applies:
29	//! `E-PROGRESSION-IS-EXISTENCE-NOT-COMMAND-1` — progression is existence, not
30	//! command. An overlay that *drives* a transition from a focus reading has
31	//! rebuilt the scheduler this substrate removed. Nothing in this module takes
32	//! `&mut` anything, and the precedent is `PhaseCensus`: one read-only pass.
33	//!
34	//! # Breadth is a POPULATION, not an entry count
35	//!
36	//! [`RowFocusMask::len`] is the antichain size — and a single shallow entry can
37	//! cover an unbounded subtree, so a mask of one entry may be far broader than a
38	//! mask of ten. Breadth here is therefore the covered **population**: a focus of
39	//! depth `d` leaves `CASCADE_UNITS − d` unconstrained 256-ary units, so it
40	//! covers `256^(CASCADE_UNITS − d)` addresses. That is the `6×2×8bit↑n` reading
41	//! at the measurement — depth buys coverage exponentially, which is the whole
42	//! reason a flat index cannot express this.
43	
44	use crate::attention_facet::RowFocusMask;
45	use crate::facet::CASCADE_UNITS;
46	use crate::kanban::KanbanColumn;
47	
48	/// The two kanban columns the crossing sits between. Named once, here, so a
49	/// caller cannot sample the wrong pair and still typecheck.
50	pub const PRE_RUBICON: KanbanColumn = KanbanColumn::Planning;
51	/// The post-crossing column — the implemental, shielding side.
52	pub const POST_RUBICON: KanbanColumn = KanbanColumn::CognitiveWork;
53	
54	/// Addresses a focus mask covers, as an exact `f64` population.
55	///
56	/// `256^12 ≈ 7.9e28` is comfortably inside `f64`, so this is exact for every
57	/// expressible focus and needs no log-space trickery. Entries are an antichain
58	/// (no entry covers another), so summing them double-counts nothing.
59	///
60	/// - empty mask → `0.0` (attention nowhere)
61	/// - one exact focus → `1.0` (one address)
62	/// - one whole-class focus → `256^12`
63	#[must_use]
64	pub fn coverage(mask: &RowFocusMask) -> f64 {
65	    mask.entries()
66	        .iter()
67	        .map(|e| 256f64.powi(i32::from(CASCADE_UNITS as u8 - e.depth())))
68	        .sum()
69	}
70	
71	/// [`coverage`] on a log₂ scale, so a mean over samples is not swamped by the
72	/// broadest one.
73	///
74	/// `log2(1 + coverage)`, and the `1 +` is **finiteness, not distinctness**: an
75	/// empty mask covers `0.0`, and `log2(0)` is `-inf`, which would poison the
76	/// mean in [`FocusTrace::breadth`] — one unsampled moment would make a whole
77	/// phase read as infinitely narrow. With the offset, empty reads `0.0`, exact
78	/// reads `1.0`, and every trace stays finite.
79	///
80	/// (An earlier version of this comment claimed the offset was what kept empty
81	/// distinct from exact. That was wrong — without it they read `-inf` and `0.0`,
82	/// already distinct — and no test could falsify it, because the assertion it
83	/// justified passed either way. The mutation that exposed it is now the test
84	/// below.)
85	#[must_use]
86	pub fn breadth_bits(mask: &RowFocusMask) -> f64 {
87	    (1.0 + coverage(mask)).log2()
88	}
89	
90	/// Overlap of two focuses as a Jaccard ratio over their **antichains**.
91	///
92	/// Deliberately entry-based rather than population-based: persistence asks
93	/// *"is the thinking still looking at the same things"*, and an entry is one
94	/// thing the thinking looked at. Two empty masks are unchanged (`1.0`) — a
95	/// focus that stays nowhere is still a focus that did not move.
96	#[must_use]
97	fn overlap(a: &RowFocusMask, b: &RowFocusMask) -> f64 {
98	    let union = a.union(b).len();
99	    if union == 0 {
100	        return 1.0;
101	    }
102	    a.intersect(b).len() as f64 / union as f64
103	}
104	
105	/// A phase's sampled attention: the focus mask, sampled repeatedly while the
106	/// work sat in one kanban column.
107	///
108	/// The order of samples is the order they were taken — [`persistence`] reads
109	/// consecutive pairs, so a shuffled trace measures something else.
110	///
111	/// [`persistence`]: Self::persistence
112	#[derive(Debug, Clone, Default, PartialEq)]
113	pub struct FocusTrace {
114	    column: Option<KanbanColumn>,
115	    samples: Vec<RowFocusMask>,
116	}
117	
118	impl FocusTrace {
119	    /// An empty trace for a column — nothing sampled yet.
120	    #[must_use]
121	    pub fn new(column: KanbanColumn) -> Self {
122	        Self {
123	            column: Some(column),
124	            samples: Vec::new(),
125	        }
126	    }
127	
128	    /// Record one sample. Takes `&mut self` on the TRACE — never on anything
129	    /// the substrate owns; a trace is the observer's own notebook.
130	    pub fn sample(&mut self, mask: RowFocusMask) {
131	        self.samples.push(mask);
132	    }
133	
134	    /// The column this trace was taken in, if it was built with one.
135	    #[must_use]
136	    pub fn column(&self) -> Option<KanbanColumn> {
137	        self.column
138	    }
139	
140	    /// How many samples the trace holds.
141	    #[must_use]
142	    pub fn len(&self) -> usize {
143	        self.samples.len()
144	    }
145	
146	    /// Is the trace empty of samples?
147	    #[must_use]
148	    pub fn is_empty(&self) -> bool {
149	        self.samples.is_empty()
150	    }
151	
152	    /// Mean [`breadth_bits`] across samples; `None` with nothing sampled.
153	    ///
154	    /// `None` rather than `0.0`, because "nothing was measured" and "attention
155	    /// covered nothing" are different facts and a mean of zero samples must not
156	    /// impersonate the second.
157	    #[must_use]
158	    pub fn breadth(&self) -> Option<f64> {
159	        if self.samples.is_empty() {
160	            return None;
161	        }
162	        Some(self.samples.iter().map(breadth_bits).sum::<f64>() / self.samples.len() as f64)
163	    }
164	
165	    /// Mean consecutive [`overlap`]; `None` with fewer than two samples.
166	    ///
167	    /// `1.0` = the focus never moved (maximally shielded); `0.0` = every sample
168	    /// looked somewhere new. Undefined for a single sample — persistence is a
169	    /// property of a SEQUENCE, and one point is not one.
170	    #[must_use]
171	    pub fn persistence(&self) -> Option<f64> {
172	        if self.samples.len() < 2 {
173	            return None;
174	        }
175	        let pairs = self.samples.windows(2).map(|w| overlap(&w[0], &w[1]));
176	        let n = self.samples.len() - 1;
177	        Some(pairs.sum::<f64>() / n as f64)
178	    }
179	}
