181	/// What the two traces say about the crossing.
182	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
183	pub enum RubiconVerdict {
184	    /// Both axes moved as Heckhausen predicts: narrower AND more persistent
185	    /// after the crossing.
186	    Crossed,
187	    /// One axis moved, the other did not. Reported as its own state rather than
188	    /// rounded to either neighbour — a half-signal is not a crossing and is not
189	    /// silence.
190	    Partial,
191	    /// Neither axis moved beyond `epsilon`. On a genuinely deliberated task
192	    /// this is the FINDING the module docs name (columns decoration, or the
193	    /// mask not recording attention); on a single-forced-candidate task it is
194	    /// the correct answer.
195	    Indistinguishable,
196	    /// An axis moved the WRONG way beyond `epsilon` — broader or less
197	    /// persistent after the crossing. Never folded into the other three: a
198	    /// contradicted model must be visible, not rounded to "no signal".
199	    Inverted,
200	}
201	
202	/// The measured reading. The two deltas are always reported; the verdict only
203	/// classifies them, so a caller can disagree with the classification without
204	/// losing the numbers.
205	#[derive(Debug, Clone, Copy, PartialEq)]
206	pub struct RubiconReading {
207	    /// `pre.breadth − post.breadth`, in bits. **Positive = narrowing**, the
208	    /// direction the implemental mindset predicts.
209	    pub breadth_drop: f64,
210	    /// `post.persistence − pre.persistence`. **Positive = shielding**.
211	    pub persistence_gain: f64,
212	    /// The classification of the pair.
213	    pub verdict: RubiconVerdict,
214	}
215	
216	/// Read the crossing from a pre- and post-Rubicon trace.
217	///
218	/// `None` when either side lacks the samples to measure — breadth needs one
219	/// sample, persistence needs two. An unmeasurable trace yields no reading at
220	/// all rather than a reading built on a default, which is the same refusal the
221	/// recipe ladder makes for an ungrounded input.
222	///
223	/// `epsilon` is the indifference band on BOTH axes, in their own units (bits
224	/// for breadth, ratio for persistence). It is a real knob: raising it turns
225	/// signals into [`Indistinguishable`](RubiconVerdict::Indistinguishable), and
226	/// lowering it admits smaller ones.
227	#[must_use]
228	pub fn read_crossing(pre: &FocusTrace, post: &FocusTrace, epsilon: f64) -> Option<RubiconReading> {
229	    let breadth_drop = pre.breadth()? - post.breadth()?;
230	    let persistence_gain = post.persistence()? - pre.persistence()?;
231	
232	    let narrowed = breadth_drop > epsilon;
233	    let broadened = breadth_drop < -epsilon;
234	    let shielded = persistence_gain > epsilon;
235	    let loosened = persistence_gain < -epsilon;
236	
237	    let verdict = if broadened || loosened {
238	        RubiconVerdict::Inverted
239	    } else if narrowed && shielded {
240	        RubiconVerdict::Crossed
241	    } else if narrowed || shielded {
242	        RubiconVerdict::Partial
243	    } else {
244	        RubiconVerdict::Indistinguishable
245	    };
246	
247	    Some(RubiconReading {
248	        breadth_drop,
249	        persistence_gain,
250	        verdict,
251	    })
252	}
